mapper.select:
SELECT 
FROM qa_conversation
WHERE owner_id = #{ownerId}
  AND deleted_at IS NULL

  AND (updated_at < #{beforeUpdatedAt}
    OR (updated_at = #{beforeUpdatedAt} AND public_id < #{beforeId}))

ORDER BY updated_at DESC, public_id DESC
LIMIT #{limit}

SELECT 
FROM qa_conversation
WHERE public_id = #{id}
  AND owner_id = #{ownerId}
  AND deleted_at IS NULL
FOR UPDATE

SELECT m.id, m.public_id, m.conversation_id, m.answer_id, a.status AS answer_status,
       m.role, m.content, m.created_at
FROM qa_message m
INNER JOIN qa_conversation c ON c.public_id = m.conversation_id
LEFT JOIN qa_answer a ON a.public_id = m.answer_id
WHERE c.public_id = #{id}
  AND c.owner_id = #{ownerId}
  AND c.deleted_at IS NULL
ORDER BY m.created_at DESC, m.public_id DESC
LIMIT #{limit}

SELECT qf.question_id AS message_id, f.public_id AS file_id, f.original_name,
       f.content_type, f.size_bytes, qf.usage_type, f.status
FROM qa_question_file qf
INNER JOIN qa_file f ON f.public_id = qf.file_id
INNER JOIN qa_conversation c ON c.public_id = f.conversation_id
WHERE c.public_id = #{id}
  AND c.owner_id = #{ownerId}
  AND c.deleted_at IS NULL
  AND f.owner_id = #{ownerId}
  AND qf.question_id IN

      #{messageId}

ORDER BY qf.created_at ASC, qf.file_id ASC
